let actions=r.editable&&!['payments','attendance'].includes(r.kind)&&!(r.kind==='tasks'&&r.status==='done')&&!(r.kind==='leaves'&&['approved','rejected'].includes(r.status))?btn('تحديث السجل','edit','pen','',`data-id="${r.id}"`):'';
