function userModal(id=null){const u=id?user(id):null;const fields=[{name:'name',label:'اسم الموظف / المدرب',required:true},{name:'username',label:'اسم الدخول بالإنجليزية',required:!u,readonly:!!u,hint:'3-40 حرفًا إنجليزيًا أو رقمًا بدون مسافات.'},{name:'role',label:'الصلاحية',type:'select',options:ROLE},{name:'dept',label:'القسم',type:'select',options:DEPT},{name:'title',label:'المسمى الوظيفي'},{name:'phone',label:'رقم التواصل'},{name:'password',label:u?'كلمة مرور مؤقتة جديدة (اختياري)':'كلمة مرور مؤقتة',type:'password',required:!u,full:true,hint:'12 حرفًا على الأقل. سيطلب النظام تغييرها عند الدخول.'},...(u?[{name:'active',label:'حالة الحساب',type:'checkbox',checkText:'الحساب فعّال'}]:[])];modalShow(u?'إدارة حساب '+u.name:'إضافة موظف / مدرب','لا تُرسل كلمة المرور عبر قنوات عامة.',`<form id="user-form" data-id="${u?.id||''}"><div class="modal-body"><div class="form-grid">${fields.map(f=>field(f,u?.[f.name]??(f.name==='role'?'employee':f.name==='dept'?'sales':''))).join('')}</div></div><div class="modal-foot"><button class="btn" type="submit">حفظ الحساب</button>${btn('إلغاء','close','','secondary')}</div></form>`)}
