function renderAuth(mode='login'){authMode=mode;page='dashboard';let setup=mode==='setup',signup=mode==='signup';app.innerHTML=`<div class="auth-shell"><section class="auth-story"><span class="brand-symbol">LAI</span><div class="eyebrow">LEADERSHIP ARTERY INSTITUTE</div><h1>إدارة أوضح.<br>تنفيذ أدق.<br><span>نتائج تراها.</span></h1><p>مساحة عمل معهد شريان القيادة لإدارة الفريق والمهام والدورات. أونلاين، مترابطة، وبصلاحيات واضحة.</p><div class="auth-points"><div><strong>04</strong>أقسام في مساحة واحدة</div><div><strong>01</strong>قاعدة موحدة للفريق</div></div></section><section class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">مساحة الإدارة التنفيذية</div><h2>${setup?'لنجهّز حساب الإدارة.':signup?'طلب حساب مدرب':'أهلًا بعودتك.'}</h2><p>${setup?'أنشئ حساب المدير العام. لا توجد كلمة مرور افتراضية.':signup?'يُراجع طلبك وتفعّله الإدارة قبل السماح بالدخول.':'سجّل الدخول لمتابعة فريقك ونتائج العمل.'}</p><form id="auth-form">${setup?field({name:'setup_token',label:'رمز تهيئة الإدارة',type:'password',required:true}):''}${setup||signup?field({name:'name',label:setup?'اسم المدير العام':'اسم المدرب',required:true}):''}${field({name:'username',label:'اسم الدخول',required:true,placeholder:'admin',maxlength:40})}${signup?field({name:'phone',label:'رقم التواصل'}):''}${field({name:'password',label:'كلمة المرور',type:'password',required:true})}${setup||signup?field({name:'confirm',label:'تأكيد كلمة المرور',type:'password',required:true}):''}${setup?`<label class="check-label"><input type="checkbox" name="demo">أضف أمثلة توضيحية للتجربة، وليست بيانات حقيقية.</label>`:''}<button class="btn" type="submit">${setup?'إنشاء النظام':signup?'إرسال طلب التفعيل':'دخول مساحة العمل'} ${icon('arrow')}</button></form><div class="auth-note">الدخول مخصص لفريق المعهد. لا تشارك حسابك أو رمز التهيئة.${!setup&&(signup||authStatus.trainer_signup)?`<br><button class="auth-link" data-action="${signup?'auth-login':'auth-signup'}">${signup?'العودة لتسجيل الدخول':'مدرب جديد؟ اطلب حسابًا'}</button>`:''}<br><a href="/help.html" target="_blank" rel="noopener">دليل البدء والاستخدام</a></div></div></section></div>`;$('#f-username')?.focus()}
async function blobBase64(file){if(!file)return'';return await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(String(fr.result).split(',')[1]);fr.onerror=()=>reject(new Error('تعذر قراءة الملف.'));fr.readAsDataURL(file)})}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function navigate(p){page=p;filters={q:'',dept:'',owner:'',status:'',priority:''};render();window.scrollTo(0,0)}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=Number(el.dataset.id);try{switch(action){
case'nav':navigate(el.dataset.page);break;
case'menu':$('.sidebar').classList.toggle('open');break;
case'close':closeModal();break;
case'new':openEditor(el.dataset.kind);break;
case'edit':{let r=getR(id);if(r)openEditor(r.kind,r);break}
case'detail':await openDetail(id);break;
case'view':taskView=el.dataset.view;render();break;
case'print':window.print();break;
case'refresh':await load();toast('تم تحديث البيانات.');break;
case'theme':{let dark=document.body.dataset.theme!=='dark';document.body.dataset.theme=dark?'dark':'light';prefSet('lai-theme',dark?'dark':'light');break}
case'logout':await api('/api/logout',{});S=null;csrf='';modal.dataset.force='';closeModal();renderAuth();break;
case'auth-signup':renderAuth('signup');break;
case'auth-login':renderAuth('login');break;
case'export':window.location.href='/api/export?kind='+encodeURIComponent(el.dataset.kind);break;
case'new-user':userModal();break;
case'edit-user':userModal(id);break;
case'password':passwordModal();break;
case'record-approve':decisionModal(id,'approve');break;
case'record-reject':decisionModal(id,'reject');break;
case'record-reopen':decisionModal(id,'reopen');break;
case'handoff':handoffModal(id);break;
case'clock-in':case'clock-out':await api('/api/clock',{action:action==='clock-in'?'in':'out'});await load();toast('تم تسجيل الوقت.');break;
case'backup':{el.disabled=true;const b=await api('/api/backup',{}, {blob:true});downloadBlob(b.blob,b.name);await load();toast('تم إنشاء النسخة وبدء تنزيلها.');break}
case'restore':restoreModal();break;
case'demo-add':if(confirm('إضافة بيانات توضيحية؟ امسحها قبل إنشاء السجلات الحقيقية.')){await api('/api/demo',{action:'add'});await load();toast('أضيفت الأمثلة التوضيحية.')}break;
case'demo-clear':if(confirm('مسح الأمثلة فقط وحساباتها التجريبية؟ ستُحفظ نسخة أمان أولًا.')){await api('/api/demo',{action:'clear'});await load();toast('مُسحت الأمثلة. النظام جاهز لبياناتك الفعلية.')}break;
case'audit-refresh':S.fullAudit=(await api('/api/audit')).events;render();break;
case'cal-prev':case'cal-next':{let [y,m]=calendarMonth.split('-').map(Number);let d=new Date(Date.UTC(y,m-1+(action==='cal-next'?1:-1),1));calendarMonth=d.toISOString().slice(0,7);render();break}
}}catch(e){toast(e.message,true)}finally{el.disabled=false}});
let searchTimer;
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='filter-q'){filters.q=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{let pos=el.selectionStart;$('#page-body').innerHTML=pageHTML();let input=$('#filter-q');input.focus();input.setSelectionRange(pos,pos)},180)}});
document.addEventListener('change',async ev=>{const el=ev.target;try{
 if(el.id.startsWith('filter-')){filters[el.id.slice(7)]=el.value;$('#page-body').innerHTML=pageHTML()}
 if(el.id==='period-month'){month=el.value||S.server_today.slice(0,7);render()}
 if(el.id==='all-periods'){allPeriods=el.checked;render()}
 if(el.id==='calendar-month'){calendarMonth=el.value||S.server_today.slice(0,7);render()}
 if(el.id==='f-data-course_id')updateDependentFields();
 if(el.id==='f-data-reversal_of'&&editor?.kind==='payments'){const original=getR(el.value);if(original){$('#f-data-type').value=original.data.type==='receipt'?'refund':'expense_return';$('#f-data-course_id').value=original.data.course_id||'';updateDependentFields();$('#f-data-enrollment_id').value=original.data.enrollment_id||'';$('#f-data-category').value=original.data.category||'other'}}
 if(el.id==='attachment-upload'){const file=el.files[0];if(!file)return;if(file.size>8*1024*1024)throw new Error('الحد الأقصى للمرفق 8 ميجابايت.');el.disabled=true;const id=Number(el.dataset.id);await api('/api/records/'+id+'/attachment',{name:file.name,content:await blobBase64(file)});await load();await openDetail(id);toast('أُرفق الملف وحُفظ داخل قاعدة البيانات.')}
 if(el.dataset.check!==undefined){let id=Number(el.dataset.id),r=getR(id),list=structuredClone(r.data.checklist);list[Number(el.dataset.check)].done=el.checked;await api('/api/records/'+id,{version:r.version,data:{checklist:list}});await load();await openDetail(id)}
}catch(e){toast(e.message,true);el.disabled=false}});
document.addEventListener('submit',async ev=>{const form=ev.target;if(!form.id)return;ev.preventDefault();const button=form.querySelector('button[type=submit]');if(button)button.disabled=true;try{const fd=new FormData(form);
switch(form.id){
case'auth-form':{const b=Object.fromEntries(fd);if(authMode!=='login'&&b.password!==b.confirm)throw new Error('كلمتا المرور غير متطابقتين.');if(authMode==='setup'){b.demo=fd.has('demo');await api('/api/setup',b);let res=await api('/api/login',{username:b.username,password:b.password});csrf=res.csrf;await load();toast('تم إنشاء نظام المعهد بنجاح.')}else if(authMode==='signup'){await api('/api/signup',b);renderAuth();toast('أُرسل الطلب. فعّل الحساب من الإدارة قبل الدخول.')}else{const res=await api('/api/login',b);csrf=res.csrf;await load()}break}
case'record-form':await saveRecord(form);break;
case'user-form':{let body=Object.fromEntries(fd);if(form.dataset.id)body.active=fd.has('active');await api(form.dataset.id?'/api/users/'+form.dataset.id:'/api/users',body);closeModal();await load();toast('تم حفظ الحساب. سلّم كلمة المرور المؤقتة لصاحبها بأمان.');break}
case'password-form':{if(fd.get('password')!==fd.get('confirm'))throw new Error('كلمتا المرور غير متطابقتين.');await api('/api/password',{current:fd.get('current'),password:fd.get('password')});modal.dataset.force='';closeModal();await load();toast('تم تغيير كلمة المرور.');break}
case'comment-form':{let id=Number(form.dataset.id);await api('/api/records/'+id+'/comment',{body:fd.get('body')});await load();await openDetail(id);toast('أضيف التعليق.');break}
case'decision-form':{let id=Number(form.dataset.id),r=getR(id);await api('/api/records/'+id+'/action',{version:r.version,action:form.dataset.decision,note:fd.get('note')});closeModal();await load();await openDetail(id);toast('تم تسجيل قرار المراجعة.');break}
case'handoff-form':await api('/api/handoff',{lead_id:Number(form.dataset.id),owner_id:Number(fd.get('owner_id')),due:fd.get('due'),notes:fd.get('notes')});closeModal();await load();toast('تم تسليم العميل وإنشاء طلب متابعة مرتبط.');break;
case'settings-form':await api('/api/settings',Object.fromEntries(fd));await load();toast('تم تحديث بيانات المعهد.');break;
case'restore-form':{const file=fd.get('backup');if(!file?.size||file.size>32*1024*1024)throw new Error('اختر نسخة صالحة لا تتجاوز 32 ميجابايت.');await api('/api/restore',{password:fd.get('password'),content:await blobBase64(file)});modal.dataset.force='';closeModal();S=null;csrf='';renderAuth();toast('اكتملت الاستعادة. ادخل ببيانات حساب موجود في النسخة المستعادة.');break}
}
}catch(e){toast(e.message,true)}finally{if(button)button.disabled=false}});
modal.addEventListener('cancel',ev=>{if(modal.dataset.force==='yes')ev.preventDefault()});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!modal.open)$('.sidebar')?.classList.remove('open')});
async function init(){try{document.body.dataset.theme=prefGet('lai-theme')||'light';const status=await api('/api/status');authStatus=status;if(status.setup_required)renderAuth('setup');else{try{await load()}catch(e){renderAuth('login')}}clearInterval(refreshTimer);refreshTimer=setInterval(()=>{if(S&&!modal.open&&document.visibilityState==='visible')load().catch(markNetworkOffline)},15000)}catch(e){app.innerHTML=`<div class="boot"><span class="brand-symbol">LAI</span><h1>تعذر فتح مساحة العمل</h1><p>${esc(e.message)}</p><button class="btn" data-action="refresh">إعادة المحاولة</button></div>`}}
init();

function markNetworkOffline(){const el=document.querySelector('.local-status');if(el){el.textContent='انقطع الاتصال · البيانات لم تحدث';el.setAttribute('role','status');}}
window.addEventListener('offline',markNetworkOffline);
window.addEventListener('online',()=>{if(S)load().catch(markNetworkOffline)});
